<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox,type UploadFile}from'element-plus';import{useRoute}from'vue-router';import{api}from'../api/admin';
const route=useRoute();const loading=ref(false),rows=ref<any[]>([]),customers=ref<any[]>([]),orders=ref<any[]>([]),history=ref<any[]>([]),historyVisible=ref(false);const filters=reactive({iccid:'',batch:'',status:String(route.query.status||''),serviceNumber:'',orderNo:''});const createVisible=ref(false),importVisible=ref(false),assignVisible=ref(false),selected=ref<any>();const createForm=reactive({iccid:'',batchNo:'',remark:''}),importForm=reactive<{batchNo:string,file:File|null}>({batchNo:'',file:null}),assignForm=reactive<any>({customerId:null,orderId:null,reason:''});
const statusLabel=(value:string)=>({AVAILABLE:'可用',ASSIGNED:'已占用',USED:'已使用',DISABLED:'已停用',REPLACED:'已替换'} as Record<string,string>)[value]||value;
function formatDateTime(value?:string|number|null){if(value===null||value===undefined||value==='')return '—';const numeric=typeof value==='number'?value:Number(value);const date=Number.isFinite(numeric)&&String(value).trim()!==''?new Date(numeric<100000000000?numeric*1000:numeric):new Date(String(value));if(Number.isNaN(date.getTime()))return String(value);return date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).replaceAll('/','-')}
async function load(){loading.value=true;try{rows.value=await api.iccids(filters) as any[]}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
async function loadRefs(){customers.value=await api.customers() as any[];orders.value=await api.orders() as any[]}
async function create(){try{await api.createIccid(createForm);ElMessage.success('ICCID 已新增');createVisible.value=false;Object.assign(createForm,{iccid:'',batchNo:'',remark:''});load()}catch(e:any){ElMessage.error(e.message)}}
function onFile(file:UploadFile){importForm.file=file.raw||null}
async function importCards(){if(!importForm.file)return ElMessage.warning('请选择文件');const data=new FormData();data.append('file',importForm.file);if(importForm.batchNo)data.append('batchNo',importForm.batchNo);try{const r:any=await api.importIccids(data);ElMessage.success(`导入完成：成功 ${r.success}，重复 ${r.duplicate}，失败 ${r.failed}`);importVisible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}
async function openAssign(row:any){selected.value=row;Object.assign(assignForm,{customerId:null,orderId:null,reason:''});await loadRefs();assignVisible.value=true}
async function assign(){try{await api.assignIccid(selected.value.inventory.id,assignForm);ElMessage.success('分配成功');assignVisible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}
async function promptAction(row:any,type:'unassign'|'disable'){try{const r=await ElMessageBox.prompt(type==='unassign'?'请输入解绑原因':'请输入停用原因','关键操作确认',{inputValidator:v=>!!v.trim()||'必须填写原因',confirmButtonText:'确认',cancelButtonText:'取消'});if(type==='unassign')await api.unassignIccid(row.inventory.id,{reason:r.value});else await api.disableIccid(row.inventory.id,{reason:r.value});ElMessage.success('操作完成');load()}catch(e:any){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.error(e.message)}}
async function markUsed(row:any){try{await ElMessageBox.confirm('确认该 ICCID 已实际使用？确认后不能解绑。','标记已使用',{type:'warning'});await api.useIccid(row.inventory.id);ElMessage.success('状态已更新');load()}catch(e:any){if(e!=='cancel'&&e!=='close'&&e?.message)ElMessage.error(e.message)}}
async function showHistory(row:any){history.value=await api.iccidHistory(row.inventory.id) as any[];historyVisible.value=true}
function exportCsv(){const head=['ICCID','批次','状态','客户','上台号码','内部订单号','UMALL订单号','分配时间','操作人'];const body=rows.value.map(r=>[r.inventory.iccid,r.inventory.batchNo,r.inventory.status,r.customerName,r.inventory.serviceNumber,r.orderNo,r.umallOrderNo,r.inventory.assignedAt,r.inventory.operatorName]);const csv='\uFEFF'+[head,...body].map(line=>line.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ICCID卡池.csv';a.click();URL.revokeObjectURL(url)}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading"><div><h1>ICCID 卡池</h1><p>管理未使用卡、已占用卡以及客户和订单配对信息。</p></div><el-button type="primary" @click="createVisible=true">单个新增</el-button></div><div class="filter-bar"><el-input v-model="filters.iccid" placeholder="ICCID" clearable/><el-input v-model="filters.batch" placeholder="批次" clearable/><el-select v-model="filters.status" placeholder="状态" clearable><el-option label="可用" value="AVAILABLE"/><el-option label="已占用" value="ASSIGNED"/><el-option label="已使用" value="USED"/><el-option label="已停用" value="DISABLED"/></el-select><el-input v-model="filters.serviceNumber" placeholder="上台号码" clearable/><el-input v-model="filters.orderNo" placeholder="订单号" clearable/><el-button @click="load">查询</el-button><div class="filter-actions"><el-button @click="importVisible=true">批量导入</el-button><el-button type="primary" @click="exportCsv">导出表格</el-button></div></div><div class="table-card"><div class="table-toolbar"><span class="table-title">卡池明细</span><span class="table-meta">共 {{rows.length}} 条</span></div><div class="table-scroll"><el-table class="desktop-data-table desktop-data-table--iccid" :data="rows" v-loading="loading" empty-text="暂无 ICCID 数据"><el-table-column label="ICCID" min-width="190"><template #default="s"><span class="code-text">{{s.row.inventory.iccid}}</span></template></el-table-column><el-table-column label="批次" min-width="110"><template #default="s">{{s.row.inventory.batchNo||'—'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.inventory.status==='AVAILABLE'?'success':s.row.inventory.status==='USED'?'info':s.row.inventory.status==='DISABLED'?'danger':'warning'">{{statusLabel(s.row.inventory.status)}}</el-tag></template></el-table-column><el-table-column prop="customerName" label="客户" min-width="100"/><el-table-column label="上台号码" min-width="130"><template #default="s">{{s.row.inventory.serviceNumber||'—'}}</template></el-table-column><el-table-column prop="orderNo" label="内部订单号" min-width="135"/><el-table-column prop="umallOrderNo" label="UMALL订单号" min-width="150"/><el-table-column label="分配时间" min-width="165"><template #default="s">{{formatDateTime(s.row.inventory.assignedAt)}}</template></el-table-column><el-table-column label="操作人" width="100"><template #default="s">{{s.row.inventory.operatorName||'—'}}</template></el-table-column><el-table-column label="操作" width="230"><template #default="s"><div class="ops"><el-button v-if="s.row.inventory.status==='AVAILABLE'" link type="primary" @click="openAssign(s.row)">分配</el-button><el-button v-if="s.row.inventory.status==='AVAILABLE'" link type="danger" @click="promptAction(s.row,'disable')">停用</el-button><el-button v-if="s.row.inventory.status==='ASSIGNED'" link type="primary" @click="markUsed(s.row)">标记使用</el-button><el-button v-if="s.row.inventory.status==='ASSIGNED'" link type="danger" @click="promptAction(s.row,'unassign')">解绑</el-button><el-button link @click="showHistory(s.row)">历史</el-button></div></template></el-table-column></el-table></div></div>
<el-dialog v-model="createVisible" title="新增 ICCID" width="480"><el-form label-position="top"><el-form-item label="ICCID"><el-input v-model="createForm.iccid" maxlength="22"/></el-form-item><el-form-item label="批次"><el-input v-model="createForm.batchNo"/></el-form-item><el-form-item label="备注"><el-input v-model="createForm.remark" type="textarea"/></el-form-item></el-form><template #footer><div class="dialog-footer"><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></div></template></el-dialog>
<el-dialog v-model="importVisible" title="批量导入 ICCID" width="560"><div class="hint-box" style="margin-bottom:16px">支持 XLS、XLSX、XLSM、CSV；首列或标题为“ICCID”的列将被导入。也兼容供应方“每行一个卡号”的纯文本清单（即使扩展名为 xlsx）。请勿上传加密文件，文件上限 10MB。</div><el-form label-position="top"><el-form-item label="库存批次"><el-input v-model="importForm.batchNo" placeholder="例如：CMHK-202608"/></el-form-item><el-form-item label="选择文件"><el-upload drag :auto-upload="false" :limit="1" accept=".xls,.xlsx,.xlsm,.csv" :on-change="onFile"><div>拖放文件到这里，或点击选择</div></el-upload></el-form-item></el-form><template #footer><div class="dialog-footer"><el-button @click="importVisible=false">取消</el-button><el-button type="primary" @click="importCards">开始导入</el-button></div></template></el-dialog>
<el-dialog v-model="assignVisible" title="分配 ICCID" width="560"><el-form label-position="top"><el-form-item label="客户"><el-select v-model="assignForm.customerId" filterable style="width:100%"><el-option v-for="c in customers" :key="c.id" :label="`${c.name||'未命名'} · ${c.phone}`" :value="c.id"/></el-select></el-form-item><el-form-item label="该客户订单"><el-select v-model="assignForm.orderId" filterable style="width:100%"><el-option v-for="o in orders.filter(x=>x.customerId===assignForm.customerId)" :key="o.id" :label="`${o.orderNo} · ${o.planName}`" :value="o.id"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="assignForm.reason"/></el-form-item></el-form><template #footer><div class="dialog-footer"><el-button @click="assignVisible=false">取消</el-button><el-button type="primary" @click="assign">确认分配</el-button></div></template></el-dialog>
<el-drawer v-model="historyVisible" title="ICCID 配对历史" size="520"><el-timeline><el-timeline-item v-for="h in history" :key="h.id" :timestamp="h.createdAt"><b>{{h.actionType}}</b><div class="muted">订单 {{h.orderId||'—'}} · 客户 {{h.customerId||'—'}} · {{h.operatorName}}</div><div v-if="h.reason">原因：{{h.reason}}</div></el-timeline-item></el-timeline></el-drawer></div></template>

